-- «Ваш бизнес снаружи» (22.10.2026, миграция 0151): в документы — новая
-- функция. Оферта: п. 3.6.4 (наблюдение по подписке) и бесплатный снимок
-- в п. 3.9, условие «только свой бизнес». Политика: п. 5.1 — передача ИНН
-- в ООО «ДАТА МАКСИМУМ» (checko.ru), новая цель 9 в Приложении №1.
-- Текст набросан без юриста (решение владельца: юрист проверит всё разом,
-- когда система соберётся и начнутся активные продажи). Замечания
-- юриста-агента 22.10 учтены: других людей не проверяем, сырые ответы
-- реестров не храним.

UPDATE legal_documents
SET content = replace(content,
      '3.6.3. ИИ-советник - предоставление Заказчику консультационной поддержки с привлечением автоматизированного инструмента «ИИ-советник» на базе технологий искусственного интеллекта, посредством каналов связи, определенных Исполнителем или силами самого Исполнителя.',
      '3.6.3. ИИ-советник - предоставление Заказчику консультационной поддержки с привлечением автоматизированного инструмента «ИИ-советник» на базе технологий искусственного интеллекта, посредством каналов связи, определенных Исполнителем или силами самого Исполнителя.
3.6.4. «Ваш бизнес снаружи» - опция Сервиса, в рамках которой Исполнитель регулярно получает из открытых государственных реестров (сведения о регистрации, налоговом режиме, реестре субъектов МСП, товарных знаках, контрольных (надзорных) мероприятиях, арбитражных делах, исполнительных производствах, банкротстве) сведения о бизнесе Заказчика по указанному им ИНН и уведомляет Заказчика об их изменении посредством Личного кабинета и подключённых каналов связи. Сведения получаются через сторонний сервис и предоставляются «как есть»: Исполнитель не гарантирует их полноту, достоверность и своевременность и не проверяет их по первоисточникам. Заказчик вправе указывать только ИНН индивидуального предпринимателя или организации, от имени которых он действует.'),
    updated_at = now()
WHERE key = 'user_agreement' AND content NOT LIKE '%3.6.4. «Ваш бизнес снаружи»%';

UPDATE legal_documents
SET content = replace(content,
      'Модуль статуса бизнеса и налогов. Заключение по результатам Теста,',
      'Модуль статуса бизнеса и налогов; разовое получение сведений о своём бизнесе из открытых реестров по ИНН («Ваш бизнес снаружи», не чаще одного раза в сутки, на условиях п. 3.6.4). Заключение по результатам Теста, регулярное наблюдение за реестрами,'),
    updated_at = now()
WHERE key = 'user_agreement' AND content LIKE '%3.9. Бесплатный доступ.%' AND content NOT LIKE '%разовое получение сведений о своём бизнесе%';

UPDATE legal_documents
SET content = replace(content,
      'Оператор не раскрывает третьим лицам и не распространяет персональные данные без согласия субъекта персональных данных.',
      'Оператор не раскрывает третьим лицам и не распространяет персональные данные без согласия субъекта персональных данных. ИНН, который Пользователь сам указал в разделе «Ваш бизнес снаружи», передаётся ООО «ДАТА МАКСИМУМ» (ИНН 4027148080, сервис checko.ru) исключительно для получения сведений о бизнесе Пользователя из открытых государственных реестров (цель 9 Приложения №1).'),
    updated_at = now()
WHERE key = 'privacy_policy' AND content NOT LIKE '%ООО «ДАТА МАКСИМУМ»%';

UPDATE legal_documents
SET content = content || '

## Цель 9. предоставление Пользователю сведений о его бизнесе из открытых государственных реестров, заполнение по ним данных профиля бизнеса в Сервисе (форма, регион, дата регистрации, налоговый режим) и уведомление об изменении сведений («Ваш бизнес снаружи»)

- Категории субъектов ПДн: пользователи сайта — индивидуальные предприниматели, указавшие ИНН своего бизнеса
- Перечень обрабатываемых ПДн: ИНН; сведения из открытых государственных реестров о бизнесе Пользователя (статус регистрации, коды ОКВЭД, налоговый режим, категория в реестре МСП, наличие товарных знаков, контрольных (надзорных) мероприятий, арбитражных дел, исполнительных производств, сообщений о банкротстве)
- Источник ПДн: Пользователь (ИНН); открытые государственные реестры, получаемые через ООО «ДАТА МАКСИМУМ» (сервис checko.ru)
- Способ обработки ПДн: Автоматизированная
- Сроки обработки и хранения ПДн: ИНН — до его удаления Пользователем или удаления учётной записи; сведения из реестров — три последних полученных набора, более ранние удаляются автоматически. Полные ответы реестров не хранятся
- Действия с ПДн по окончании обработки: Персональные данные подлежат уничтожению в течение 30 дней с момента удаления учётной записи или отзыва согласия на обработку персональных данных',
    updated_at = now()
WHERE key = 'privacy_policy' AND content NOT LIKE '%## Цель 9.%';
